solution.Bill.java:
import java.math.*;
import java.util.*;

public final class Bill {
    public static List<BigDecimal> split(String amount, int people) {
        if (people < 1) throw new IllegalArgumentException("at least one person");
        BigInteger pennies = new BigDecimal(amount).setScale(2, RoundingMode.UNNECESSARY).unscaledValue();
        BigInteger[] qr = pennies.divideAndRemainder(BigInteger.valueOf(people));
        List<BigDecimal> parts = new ArrayList<>();
        for (int i = 0; i < people; i++) {
            BigInteger p = qr[0].add(i < qr[1].intValue() ? BigInteger.ONE : BigInteger.ZERO);
            parts.add(new BigDecimal(p, 2));
        }
        return parts;
    }

    public static BigDecimal withTip(String amount, String percent) {
        BigDecimal a = new BigDecimal(amount);
        BigDecimal tip = a.multiply(new BigDecimal(percent)).divide(BigDecimal.valueOf(100));
        return a.add(tip).setScale(2, RoundingMode.HALF_UP);
    }
}

unitTests:
test("splits add up exactly", () -> {
    checkEq(Bill.split("100.00", 3).toString(), "[33.34, 33.33, 33.33]");
    checkEq(Bill.split("0.05", 2).toString(), "[0.03, 0.02]");
    checkEq(Bill.split("10", 4).toString(), "[2.50, 2.50, 2.50, 2.50]");
    java.math.BigDecimal total = java.math.BigDecimal.ZERO;
    for (java.math.BigDecimal p : Bill.split("1234.57", 7)) total = total.add(p);
    checkEq(total.compareTo(new java.math.BigDecimal("1234.57")), 0);
});

test("people must be at least one", () -> {
    checkThrows(IllegalArgumentException.class, () -> Bill.split("10.00", 0));
});

test("tips round half up", () -> {
    checkEq(Bill.withTip("84.50", "15").toString(), "97.18");
    checkEq(Bill.withTip("10.00", "12.5").toString(), "11.25");
    checkEq(Bill.withTip("0.10", "5").toString(), "0.11");
});

